import { type ReactNode } from "react";
import { Button } from "./button";

// KMP-C30 (specs/KMP-C30-zero-results.md). In place of both result groups when a query matches nothing.
// Not a live region: the consumer announces the statement. The consumer also returns focus to the search field after the action.

export type ZeroResultsProps = {
  /** The query exactly as typed: not trimmed, not escaped, any script. */
  query: string;
  queryLang?: string;
  /** The active role chip's name, verbatim ("saar"). Switches the statement and the action to the role variant. */
  role?: string;
  /** All recipes searched by name. */
  total: number;
  /** Recipes whose ingredients were searched. When equal to total the "searched by name only" sentence is not rendered. */
  extracted: number;
  /** Clear search, or Show all roles when a role is active. */
  onAction: () => void;
  /** Copy, for translated builds. */
  copy?: { noDishes: string; noRole: (role: string) => string; clearSearch: string; showAllRoles: string };
};

const english = { noDishes: "No dishes match", noRole: (r: string) => `No ${r} match`, clearSearch: "Clear search", showAllRoles: "Show all roles" };

export function ZeroResults({ query, queryLang, role, total, extracted, onAction, copy = english }: ZeroResultsProps) {
  if (query === "") return null; // never an empty shell
  const rest = total - extracted;
  const lead: ReactNode = role ? copy.noRole(role) : copy.noDishes;
  return (
    <div className="flex flex-col gap-stack-md rounded-card border-bw-default border-border-card bg-surface-raised p-inset-md font-body leading-normal">
      <p className="text-ui-subtitle font-semibold text-text [overflow-wrap:anywhere]">
        {lead} "<span lang={queryLang} className="whitespace-pre-wrap">{query}</span>".
      </p>
      <p className="text-ui-reading font-regular text-text-muted">
        Searched dish names and Kannada names in all {total} recipes, and ingredients in {extracted}.
      </p>
      {rest > 0 && (
        <p className="text-ui-reading font-regular text-text-muted">
          The other {rest} were searched by name only, so a dish may use it without being found.
        </p>
      )}
      <Button variant="outline" fullWidth onClick={onAction}>
        {role ? copy.showAllRoles : copy.clearSearch}
      </Button>
    </div>
  );
}
